mapper.select:
/* 삭제되지 않은 반려동물 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM PET
        WHERE PET_SN = #{petSn}
          AND DEL_YN = 'N'
       )

/* 회원의 반려동물 양육 역할 코드 조회 */
SELECT R.BRUP_ROLE_CD
  FROM BRUP_REL R
  JOIN PET P
    ON P.PET_SN = R.PET_SN
 WHERE R.PET_SN = #{petSn}
   AND R.MBR_SN = #{mbrSn}
   AND R.USE_YN = 'Y'
   AND P.DEL_YN = 'N'
